    @Test void queueEventStreamRequiresBearerAndSupportsReplay()throws Exception{services();ticket(customer);mvc.perform(get("/api/v1/customer/dinitickets/stream").header("Authorization","Bearer "+customer).accept("text/event-stream")).andExpect(status().isOk()).andExpect(request().asyncStarted());call("GET","/customer/dinitickets/events",null,null).andExpect(status().isUnauthorized());}

    JsonNode ticketPreorder(JsonNode t)throws Exception {
        String menu=foodItem().path("id").asText();
        jdbc.update("update menu_items set dini_ticket_pre_order_available=true where id=?",UUID.fromString(menu));
        return data(postKey("/customer/orders",Map.of("restaurantId",restaurant,"diniTicketId",t.path("id").asText(),"orderType","DINITICKET_PREORDER","items",orderLines(menu)),customer,key()).andExpect(status().isCreated()));
    }
    @Test void ticketExpiryCancelsOnlyUnacceptedPreorder()throws Exception {
        services();var t=ticket(customer);var order=ticketPreorder(t);
        jdbc.update("update dini_tickets set expires_at=? where id=?",java.sql.Timestamp.from(Instant.parse("2026-09-13T09:59:00Z")),UUID.fromString(t.path("id").asText()));
        ticketService.expireRestaurant(UUID.fromString(restaurant));
        call("GET","/customer/orders/"+order.path("id").asText(),null,customer).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("CANCELLED"));
        assertThat(jdbc.queryForObject("select status from dini_tickets where id=?",String.class,UUID.fromString(t.path("id").asText()))).isEqualTo("EXPIRED");
    }
    @Test void acceptedTicketPreorderDefersExpiryAndRequiresSeatingBeforeServing()throws Exception {
        services();var t=ticket(customer);var order=ticketPreorder(t);String url=path("/orders/"+order.path("id").asText());
        order=data(call("PUT",url+"/accept",action(order),owner).andExpect(status().isOk()));
        jdbc.update("update dini_tickets set expires_at=? where id=?",java.sql.Timestamp.from(Instant.parse("2026-09-13T09:59:00Z")),UUID.fromString(t.path("id").asText()));
        ticketService.expireRestaurant(UUID.fromString(restaurant));
        t=data(call("GET","/customer/dinitickets/"+t.path("id").asText(),null,customer).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("WAITING")).andExpect(jsonPath("$.data.expiryDeferredByPreorder").value(true)));
        order=data(call("PUT",url+"/prepare",action(order),owner).andExpect(status().isOk()));
        order=data(call("PUT",url+"/ready",action(order),owner).andExpect(status().isOk()));
        call("PUT",url+"/serve",action(order),owner).andExpect(status().isConflict());
        t=ticketAction(ticketAction(t,"call"),"arrived");
        t=data(call("PUT",path("/dinitickets/"+t.path("id").asText()+"/seat"),Map.of("version",t.path("version").asLong(),"reason","Seated without a managed table"),owner).andExpect(status().isOk()));
        call("PUT",path("/dinitickets/"+t.path("id").asText()+"/complete"),action(t),owner).andExpect(status().isConflict());
        order=data(call("PUT",url+"/serve",action(order),owner).andExpect(status().isOk()));
        call("PUT",url+"/complete",action(order),owner).andExpect(status().isOk());
        cashPay("DINITICKET",t.path("id").asText());assertThat(ticketAction(t,"complete").path("status").asText()).isEqualTo("COMPLETED");
    }
    JsonNode cashPay(String type,String id)throws Exception {var p=data(postKey("/customer/payments/create-order",Map.of("referenceType",type,"referenceId",id,"gateway","CASH"),customer,key()).andExpect(status().isCreated()));return data(call("PUT",path("/payments/"+p.path("id").asText()+"/confirm-cash"),action(p),owner).andExpect(status().isOk()));}
